{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "For other students to be eligible, they must have a specific disability defined by the state board of education and an active individualized education program (IEP) listing that disability as primary or secondary.",
      "rationale": "Conveys the disability and IEP requirements, but omits the enumerated qualifying disabilities, Tennessee residency for this route, and the requirement that the IEP be in effect when the department receives the participation request."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "These students must also have been enrolled in a Tennessee public school for the previous full year, be enrolling in a Tennessee school for the first time, or have received an individualized education account (IEA) in the previous year.",
      "rationale": "Conveys the three alternative eligibility histories, but omits actual attendance in addition to enrollment and does not clearly tie the full preceding school year to the school year of receiving an IEA."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "It expands the definition of an eligible student to include Tennessee residents who are entitled to attend public school but have a medical condition that prevents them from attending in person, as determined by the state board of education.",
      "rationale": "Conveys the separate medical-condition route, residency, public-school entitlement, and state board determination. However, 'prevents' narrows the bill's condition that the medical condition 'inhibits' in-person attendance."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For students with this medical condition, a home school would be considered a participating school.",
      "rationale": "Conveys home-school participation for the medical-condition route, but omits the independent definition covering nonpublic schools that meet Part 14 requirements and seek to enroll eligible students."
    },
    {
      "proposition_id": "P5",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not convey the exemption of medical-route students and participating home schools from § 49-10-1404."
    },
    {
      "proposition_id": "P6",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not mention limiting the participating-school references in § 49-10-1403(d) and § 49-10-1405(a)(7) to qualifying nonpublic schools."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Parents of students with qualifying medical conditions must use IEA funds only for approved expenses.",
      "rationale": "Conveys the parents' obligation to restrict medical-route IEA funds to approved expenses; the omitted statutory cross-reference is not essential here."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The department would be required to monitor these funds for compliance",
      "rationale": "Conveys mandatory department monitoring of the medical-route funds, but omits creating and implementing a process and the requirement that monitoring be regular."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The department would be required to monitor these funds for compliance and may suspend or permanently terminate a student's participation in the program if the parent fails to follow these rules.",
      "rationale": "Conveys the department's discretionary suspension or termination authority conditioned on parental noncompliance with the new requirements."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "may suspend or permanently terminate a student's participation in the program if the parent fails to follow these rules.",
      "rationale": "Describing termination as permanent conveys that a student terminated for parental noncompliance cannot participate in the future."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The bill would take effect on July 1, 2026.",
      "rationale": "States the effective date accurately."
    }
  ]
}
